R("function viewHomeLegacy(){\n  if(S.sharedIn&&S.user){S.draft={casetext:S.sharedIn,fromShare:true};S.sharedIn=null;try{sessionStorage.removeItem(\"sorted.sharedIn\")}catch(e){}S.composeOpen=true;S.draft.matchId=null}\n  var yours=[],waiting=[],upcoming=[],done=[];\n  S.tasks.forEach(function(t){var s=state(t);(s===\"done\"?done:(s===\"waiting\"||s===\"waitdue\")?waiting:s===\"upcoming\"?upcoming:yours).push(t)});\n  upcoming.sort(function(a,b){return startBy(a.renew)-startBy(b.renew)});\n  var h=topbar();\n  h+='<main class=\"stack fade\" style=\"gap:28px;margin-top:8px\">';\n  var active=yours.length+waiting.length+upcoming.length,entryFirst=!active&&S.loaded;\n  if(!entryFirst)h+='<h1 class=\"sr-only\">Your cases</h1>';\n  if(entryFirst)h+=art(\"hero-case\",\"hero\",true);\n  if(entryFirst)h+=caseEntry();\n  if(entryFirst&&!S.tasks.some(function(x){return x.example}))h+='<p class=\"muted\" style=\"font-size:16px;margin-top:-12px\">Not ready yet? <button class=\"link\" data-a=\"example\" style=\"display:inline-block;padding:10px 0\">See how it works with an example case</button></p>';\n  h+=anonNote();\n  if(!S.tasks.length&&!S.loaded){\n    h+='<p class=\"muted\">Opening your cases…</p>';\n  }else if(!S.tasks.length){\n    h+='<section class=\"stack\"><div class=\"group-h\"><h2 class=\"h3\">Your cases</h2><span class=\"mono muted\">0</span></div>';\n    h+='<p class=\"muted\">Nothing here yet. Start with what you need to sort out, and Sorted will keep the next step here.</p>';\n    h+='<div class=\"slip yellow example\" aria-hidden=\"true\"><span class=\"example-tag\">EXAMPLE</span><div class=\"slip-main\"><span class=\"slip-title\">Washing machine</span></div><div class=\"slip-stub\"><span><span class=\"flag\">Waiting on Oakridge</span></span><span class=\"mono\">Tue 14:00–16:00 · A1842</span></div></div>';\n    h+='</section>';\n  }else{\n    var held=waiting.length+upcoming.length;\n    if(!yours.length&&held)h+='<section class=\"calm stack-s\">'+art(\"state-waiting\",\"state\")+'<p class=\"h2\">Nothing needs you right now.</p><p>Sorted is holding '+held+' thing'+(held===1?\"\":\"s\")+' for you. You can put '+(held===1?\"it\":\"them\")+' down for now.</p></section>';\n    h+=group(\"Needs you\",yours);\n    h+=inboxBlock();\n    h+=group(\"Waiting\",waiting,yours.length?art(\"state-waiting\",\"group\"):\"\");\n    h+=group(\"Coming up\",upcoming);\n    if(!entryFirst){\n      var answering=yours.some(function(x){var xp=openPromise(x);return xp&&!openMove(x)&&phase(xp)===\"check\"});\n      h+='<div class=\"compose-wrap\">'+(S.composeOpen?caseEntry():answering?'<button class=\"link compose-mini\" data-a=\"compose\" aria-label=\"Start another case\">+ New case</button>':'<button class=\"btn block compose\" data-a=\"compose\">+ Sort something else</button>')+'</div>';\n    }\n    h+=winsBlock();\n    if(done.length)h+='<details class=\"group\"><summary class=\"group-h\"><h2 class=\"h3\">Done</h2><span class=\"mono muted\">'+done.length+' finished</span></summary>'+done.map(function(x){return slip(x)}).join(\"\")+'</details>';\n  }\n\n  h+='</main>';\n  return h;\n}\n",
  "");
